  "mach-ohp":{img:"Machine_Shoulder_Military_Press",steps:["Set the seat so the handles start at shoulder height.", "Press the handles up until your arms are almost straight.", "Lower slowly."],tips:["Back against the pad; don't arch to finish."]},
  "push-press":{img:"Push_Press",steps:["Start with the bar on your front shoulders.", "Dip a few inches at the knees, then drive up hard with the legs.", "Use that drive to press the bar overhead and lock out."],tips:["Dip straight down, chest up.", "Lower to the shoulders under control."]},
  "landmine-press":{steps:["Hold the end of a landmine bar at your shoulder in a split stance.", "Press it up and forward until your arm is straight.", "Lower it back to the shoulder."],tips:["Shoulder-friendly; good if overhead pressing hurts.", "Do all reps on one side, then switch."]},
  "db-shrug":{img:"Dumbbell_Shrug",steps:["Stand holding dumbbells at your sides.", "Lift your shoulders straight up toward your ears.", "Lower all the way."],tips:["Straight up and down, no rolling.", "Pause at the top."]},
  "ez-curl":{img:"EZ-Bar_Curl",steps:["Hold the EZ bar on the angled grips, arms straight.", "Curl it up with elbows by your sides.", "Lower to straight arms."],tips:["Kinder to the wrists than a straight bar.", "No swinging."]},
