  "wrist-curl":{img:"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench",steps:["Rest your forearms on a bench, wrists over the edge, palms up.", "Curl the weight up using only your wrists.", "Lower slowly."],tips:["Small range, high reps."]},
  "cable-oh-ext":{img:"Cable_Rope_Overhead_Triceps_Extension",steps:["Face away from a pulley holding a rope behind your head.", "Extend your arms forward and up until they are straight.", "Return slowly to a deep bend."],tips:["Elbows stay pointed forward.", "The overhead stretch is what makes it work."]},
