  "seated-leg-curl":{img:"Seated_Leg_Curl",steps:["Sit with the pad above your heels and the thigh pad down snug.", "Curl your heels down and back.", "Return slowly."],tips:["Lean forward slightly for more hamstring stretch.", "Control the return."]},
