  "nordic":{img:"Natural_Glute_Ham_Raise",near:1,steps:["Kneel with your ankles anchored, body straight from knees to head.", "Lower yourself forward as slowly as you can, using your hamstrings to resist.", "Catch yourself with your hands and push back up."],tips:["Slow lowering is the exercise; the way up can be assisted.", "Hips stay straight; don't bend at the waist."]},
