  "smith-squat":{img:"Smith_Machine_Squat",steps:["Set the bar on your upper back and feet slightly in front of you.", "Squat down until your thighs are at least parallel.", "Drive back up."],tips:["Foot position changes everything; find one that feels natural.", "Use the safeties."]},
  "reverse-lunge":{img:"Dumbbell_Rear_Lunge",steps:["Stand tall holding dumbbells.", "Step back and lower until your back knee nearly touches the floor.", "Push through the front foot to return."],tips:["Easier on the knees than forward lunges.", "Keep the torso upright."]},
