  "side-plank":{img:"Side_Bridge",steps:["Lie on your side, forearm under your shoulder, feet stacked.", "Lift your hips so your body is straight from head to heels.", "Hold, then switch sides."],tips:["Hips forward and up; don't sag.", "Knees down makes it easier."]},
  "woodchop":{img:"Standing_Cable_Wood_Chop",steps:["Set a pulley high and stand side-on, holding the handle with both hands.", "Pull it diagonally down across your body to the opposite hip.", "Return slowly."],tips:["Turn through the hips and torso; arms stay long.", "Do both sides."]},
  "suitcase-carry":{steps:["Pick up one heavy dumbbell or kettlebell.", "Walk tall without leaning toward the weight.", "Switch hands and walk back."],tips:["Works the side of the core.", "Shoulders level, no lean."]},
