  "easy-run":{steps:["Run at a pace where you could talk in full sentences.", "Keep a relaxed, steady rhythm.", "Walk breaks are fine; the time is the goal."],tips:["Most of your running should feel this easy.", "Log the time; add the distance if you know it."]},
  "long-run":{steps:["Run at an easy, conversational pace.", "Keep it steady from start to finish.", "Build the time gradually from week to week."],tips:["Easy pace: the length is what builds the base."]},
