  "ruck":{steps:["Pack the weight high and tight against your back.", "Walk briskly with short, quick steps.", "Keep an upright posture."],tips:["Build weight and distance slowly.", "Good boots and dry socks matter more than speed."]},
  "rower":{img:"Rowing_Stationary",steps:["Strap your feet in and grab the handle.", "Push with the legs, then lean back slightly and pull the handle to your lower ribs.", "Return arms, then body, then legs."],tips:["Legs, body, arms on the drive; arms, body, legs on the way back.", "Most of the power is from the legs."]},
  "bike-erg":{img:"Bicycling_Stationary",steps:["Set the seat so your knee is slightly bent at the bottom of the pedal stroke.", "Pedal at a steady cadence.", "Adjust resistance to the effort you want."],tips:["Seat height is everything; too low hurts the knees."]},
  "jump-rope":{img:"Rope_Jumping",steps:["Hold the handles with elbows close to your sides.", "Turn the rope with your wrists and jump just high enough to clear it.", "Land softly on the balls of your feet."],tips:["Small, quick jumps.", "Rope length: handles reach your armpits when you stand on the middle."]},
  "treadmill-run":{steps:["Start the belt slowly, then bring it up to your pace.", "Run tall in the middle of the belt, not at the front edge.", "Slow the belt down before you step off."],tips:["A 1% incline is closer to running outdoors.", "Copy the distance from the console when you finish."]},
  "walk":{steps:["Walk at a pace that raises your breathing a little.", "Stand tall and let your arms swing.", "Keep it steady; the time is the goal."],tips:["A brisk walk counts as cardio.", "Add the distance if you know it."]},
  "incline-walk":{steps:["Set the incline (10–15% is common) and a walking speed you can hold.", "Walk tall without holding the rails.", "Lower the incline before you slow down."],tips:["Holding the rails takes most of the work away.", "Shorter steps are easier on the calves."]},
  "elliptical":{steps:["Step on, hold the handles and start moving.", "Push and pull through the handles as the pedals go round.", "Set the resistance for the effort you want."],tips:["Keep your heels down to work the legs more.", "Low impact: easy on knees and shins."]},
